CREATE TABLE IF NOT EXISTS tahfidz_entries (id CHAR(36) PRIMARY KEY,student_id CHAR(36) NOT NULL,activity_date DATE NOT NULL,surah VARCHAR(120) NOT NULL,ayah_start INT NOT NULL,ayah_end INT NOT NULL,juz INT NULL,page_no INT NULL,activity_type VARCHAR(32) NOT NULL,score DECIMAL(5,2) NULL,fluency VARCHAR(64) NULL,tajwid VARCHAR(64) NULL,makhraj VARCHAR(64) NULL,teacher_note VARCHAR(1000) NULL,teacher_user_id CHAR(36) NOT NULL,verification_status VARCHAR(32) NOT NULL DEFAULT 'VERIFIED',created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_tahfidz_student_date(student_id,activity_date));
CREATE TABLE IF NOT EXISTS tahfidz_targets (id CHAR(36) PRIMARY KEY,student_id CHAR(36) NOT NULL,target_juz DECIMAL(5,2) NOT NULL,target_date DATE NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_target_student(student_id));
